export const GLOSSARY_SHARD = Object.freeze({"circulating-supply":{"slug":"circulating-supply","cat":"basics","en":"Circulating supply","contentLocale":"ja","term":"流通供給量","aka":["流通量","循環供給量","Circulating supply"],"short":"流通供給量とは、現在市場で自由に取引できる状態にある暗号資産の枚数のことで、ロック中のトークンやまだ発行されていない分は含まれません。","body":[[["暗号資産","cryptocurrency"],"の供給量には主に3種類あります。今取引できる「流通供給量」、発行済みの全量である「総供給量」、将来分も含めた発行上限の「最大供給量」です。",["時価総額","market-capitalization"],"の計算には流通供給量が使われます。"],["流通供給量は時間とともに変わります。新規発行（",["マイニング","mining"],"報酬や",["ステーキング報酬","staking"],"）や",["アンロック","token-unlock"],"で増え、",["トークンバーン（焼却）","token-burn"],"で減ることがあります。ビットコインは新規発行によって少しずつ増え、最大供給量の2100万枚に近づいていきます。"],"どのトークンを「流通」に含めるかは、データサイトやプロジェクトによって判断が分かれます。財団や取引所が保有する分の扱いが違えば、流通量も時価総額も変わります。公式のトークノミクス資料とデータサイトの数字を見比べる習慣をつけましょう。"],"example":"例えば、総供給量10億枚のトークンで、流通供給量が3億枚、毎月2,000万枚がアンロックされる計画だとします。1年後には流通量が3億 + 2,000万 × 12 = 5.4億枚になり、80%増えます。価格が1ドルのままなら時価総額は3億ドルから5.4億ドルに増えますが、実際には増えた供給を吸収するだけの需要が必要です。","mistakes":["流通供給量と最大供給量を混同し、時価総額を誤って計算すること。","流通量が今後どれだけ増えるかを確認せずに保有を続けること。","データサイトごとの流通量の違いを、どちらかが間違っていると決めつけること。"],"faq":[{"q":"流通供給量と総供給量の違いは何ですか？","a":"総供給量は発行済みの全量で、ロック中のトークンも含みます。流通供給量は、そのうち市場で自由に取引できる分だけを指します。"},{"q":"流通供給量が増えると価格は下がりますか？","a":"需要が変わらなければ下押し圧力になりやすいですが、必ず下がるとは限りません。需要の伸び方によって結果は変わります。"}],"title":"流通供給量とは？総供給量・最大供給量との違い","description":"暗号資産の流通供給量の意味、総供給量や最大供給量との違い、アンロックや焼却で増減する仕組みを解説します。","related":[["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"],["fully-diluted-valuation","完全希薄化後時価総額（FDV）","完全希薄化後時価総額（FDV）とは、トークンの現在価格に最大供給量（または総供給量）を掛けた値で、将来すべてのトークンが流通した場合の評価額を示します。"],["token-unlock","トークンアンロック","トークンアンロックとは、チームや投資家などに配分されロックされていたトークンが、決められたスケジュールに従って売却や移転できるようになることです。"],["token-burn","トークンバーン（焼却）","トークンバーン（焼却）とは、トークンを誰も取り出せないアドレスに送ったりコントラクトで消滅させたりして、流通から永久に取り除くことです。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"bear-market":{"slug":"bear-market","cat":"basics","en":"Bear market","contentLocale":"ja","term":"弱気相場（ベアマーケット）","aka":["ベア相場","ベアマーケット","下落相場","Bear market"],"short":"弱気相場（ベアマーケット）とは、価格が長期間にわたって下落傾向を続け、悲観的な見方が市場に広がっている相場のことです。","body":[["熊（ベア）が前足を上から振り下ろす様子が由来とされます。株式市場では高値から20%以上の下落が目安とされることがありますが、",["暗号資産","cryptocurrency"],"の弱気相場では、主要銘柄でも高値から50%以上、小型銘柄では90%以上下落することもあります。"],["弱気相場では",["出来高","trading-volume"],"が減り、悪いニュースに敏感に反応しやすくなります。途中で一時的に大きく反発する「ベアマーケットラリー」も起こるため、底を見極めるのは困難です。"],["弱気相場での選択肢には、現物を少しずつ積み立てる、",["ステーブルコイン","stablecoin"],"で待機する、先物でショート（売り）を使うなどがあります。ただし、ショートは急な反発で損失や",["強制ロスカット","liquidation"],"につながることがあるため、仕組みを理解してから使う必要があります。"]],"example":["例えば、ある",["アルトコイン","altcoin"],"が高値の10ドルから80%下落して2ドルになったとします。元の10ドルに戻るには、2ドルから400%（5倍）の上昇が必要です。下落率と、元に戻るために必要な上昇率は同じではありません。50%下落なら必要な上昇は100%、90%下落なら900%になります。"],"mistakes":["「もう十分下がった」と考え、根拠なく全資金で底値買いを狙うこと。","一時的な反発を相場の転換と思い込み、レバレッジで買い向かうこと。","回復に必要な上昇率を考えずに、大きく下がった小型銘柄のナンピン買いを繰り返すこと。"],"faq":[{"q":"弱気相場ではどうすればいいですか？","a":"決まった正解はありませんが、資金管理を見直し、生活資金を投じないことが基本です。積立やステーブルコインでの待機など、自分のルールに合った方法を選びます。"},{"q":"弱気相場と調整の違いは何ですか？","a":"調整は上昇トレンドの途中での一時的な下落を指し、弱気相場はより長期で大きな下落トレンドを指します。両者の境界に明確な定義はありません。"}],"title":"弱気相場（ベアマーケット）とは？意味と向き合い方","description":"弱気相場（ベアマーケット）の意味と特徴、下落からの回復に必要な上昇率、弱気相場で気をつけるべき点を解説します。","related":[["bull-market","強気相場（ブルマーケット）","強気相場（ブルマーケット）とは、価格が長期間にわたって上昇傾向を続け、市場参加者の間に楽観的な見方が広がっている相場のことです。"],["fud","FUD（ファッド）","FUDとは「Fear, Uncertainty and Doubt（恐怖・不確実性・疑念）」の略で、市場に不安を広げ、売りを誘うような情報や雰囲気のことです。"],["dollar-cost-averaging","ドルコスト平均法（DCA）","ドルコスト平均法（DCA）とは、価格に関係なく一定の金額を定期的に買い続けることで、購入タイミングを分散させる投資手法です。"],["short-selling","空売り（ショートセリング）","空売り（ショートセリング）とは、持っていない資産を先に売り、後で値下がりしたところで買い戻して差額を利益にする取引方法です。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"leverage":{"slug":"leverage","cat":"derivatives","en":"Leverage","contentLocale":"ja","term":"レバレッジ","aka":["レバ","倍率","leverage"],"short":"レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。","body":["例えば10倍のレバレッジなら、1,000 USDTの証拠金で10,000 USDT分のポジションを持てます。価格が1%動くと、証拠金に対しては約10%の損益になります。レバレッジは資金効率を上げる道具ですが、少ない値動きで証拠金を失いやすくなる道具でもあります。",["レバレッジが高いほど、",["強制ロスカット（清算）","liquidation"],"価格が建値に近づきます。証拠金が",["維持証拠金","maintenance-margin"],"を下回るとポジションが強制的に決済されるため、10倍なら約10%未満、50倍なら約2%未満の逆行で清算される可能性があります。実際の",["清算価格","liquidation-price"],"は維持証拠金率や手数料によって変わるので、注文画面で確認してください。"],["海外の大手取引所では最大100倍以上を選べる銘柄もありますが、取引所や銘柄、",["ポジションサイズ","position-sizing"],"によって上限は異なります。日本国内の登録業者では、個人向けの",["暗号資産","cryptocurrency"],"デリバティブのレバレッジは最大2倍に制限されています。"]],"example":["BTCが50,000 USDTのとき、証拠金1,000 USDTで10倍、つまり0.2 ",["BTC","bitcoin"],"（10,000 USDT分）のロングを持つとします。BTCが5%上がって52,500 USDTになれば利益は500 USDTで、証拠金の50%です。逆に5%下がって47,500 USDTになれば500 USDTの損失です。約10%下がれば理論上は証拠金がほぼゼロになりますが、維持証拠金があるため実際にはその手前で清算されます。"],"mistakes":["高いレバレッジほど儲かりやすいと考え、清算価格までの距離を確認しない。","レバレッジの倍率だけを見て、実際のポジションサイズと損失額を計算しない。","清算価格より手前に損切りを置かず、証拠金の全額を失う。"],"faq":[{"q":"初心者は何倍のレバレッジが安全ですか？","a":"安全な倍率というものはなく、大事なのは損切り幅とポジションサイズです。低い倍率でも損切りを置かなければ大きな損失になり得ます。"},{"q":"日本ではレバレッジは何倍まで使えますか？","a":"国内の暗号資産交換業者では、個人向けの暗号資産デリバティブ取引のレバレッジ上限は2倍です。"}],"title":"レバレッジとは？暗号資産取引での意味と仕組み","description":"レバレッジの意味と仕組み、倍率と損益の関係、清算価格が近づく理由、日本の2倍規制までを具体的な計算例で解説します。","related":[["margin-trading","証拠金取引（マージン取引）","証拠金取引（マージン取引）とは、証拠金を担保として取引所から資金や暗号資産を借り、手持ちの資金より大きな金額で売買する取引方法です。"],["liquidation-price","清算価格（ロスカット価格）","清算価格（ロスカット価格）とは、マーク価格がその水準に達するとポジションが強制ロスカットされる価格のことで、レバレッジと維持証拠金率によって決まります。"],["initial-margin","当初証拠金（イニシャルマージン）","当初証拠金（イニシャルマージン）とは、レバレッジをかけたポジションを新しく建てるときに、最低限差し入れる必要がある証拠金の額のことです。"],["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。"],["position-sizing","ポジションサイジング（建玉管理）","ポジションサイジングとは、1回の取引でどれだけの数量を建てるかを、許容できる損失額と損切りまでの距離から逆算して決める資金管理の方法です。"]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10倍レバレッジ：お金が増えるのか、リスクが増えるのか？"},"coin":null,"tool":"/liquidations","cta":true},"auto-deleveraging":{"slug":"auto-deleveraging","cat":"derivatives","en":"Auto-deleveraging (ADL)","contentLocale":"ja","term":"自動デレバレッジ（ADL）","aka":["ADL","自動減債","オートデレバレッジ","auto-deleveraging"],"short":"自動デレバレッジ（ADL）とは、清算されたポジションの損失を保険基金で補いきれないときに、反対側で利益が出ているトレーダーのポジションを取引所が強制的に縮小する仕組みです。","body":[[["強制ロスカット","liquidation"],"されたポジションは、通常は市場で決済され、証拠金を超える損失が出た場合は",["保険基金","insurance-fund"],"で埋められます。しかし相場が極端に急変して板が薄くなると、清算注文を市場で処理できなかったり、保険基金が不足したりすることがあります。そのとき最後の手段として使われるのがADLです。"],["ADLの対象になるのは、清算されたポジションと反対方向に持っていて、利益が出ているトレーダーです。多くの取引所では、利益率と",["レバレッジ","leverage"],"が高い人ほど優先順位が上がり、取引画面にランプやメーターで順位が表示されます。対象になると、ポジションの一部または全部が",["清算価格","liquidation-price"],"に近い価格で自動的に決済されます。"],"ADLで決済されても損失を被るわけではありませんが、持ち続けたかったポジションが途中で閉じられ、その後の利益を逃すことになります。ADLが発動する頻度や順位の計算方法は取引所によって異なります。"],"example":["ある急落で、",["ロング","long-and-short"],"の大口ポジションが清算されたものの、板が薄く破産価格より大きく不利な価格でしか処理できず、保険基金でも埋められない損失が出たとします。このときショート側で、",["含み益","unrealized-pnl"],"が100%、レバレッジ25倍の人がADLの順位で最上位にいれば、その人のショート5 BTCのうち2 BTCが自動的に決済されます。利益は確定しますが、残りの3 BTCだけが残り、その後の値下がり分の利益は2 BTC分を逃します。"],"mistakes":["利益が出ているポジションなら絶対に途中で閉じられないと思い込む。","高いレバレッジで大きな含み益を出しているほど、ADLの順位が上がることを知らない。","取引画面のADL順位の表示を気にせず、急変時に突然ポジションが減って驚く。"],"faq":[{"q":"ADLで損をすることはありますか？","a":"ADLの対象になるのは利益が出ているポジションなので、決済自体は利益の確定です。ただし、その後に続くはずだった利益を逃すことになります。"},{"q":"ADLを避ける方法はありますか？","a":"レバレッジを下げたり、大きな含み益の一部を利益確定したりすると順位が下がります。完全に避ける方法はありません。"}],"title":"自動デレバレッジ（ADL）とは？発動する仕組み","description":"自動デレバレッジ（ADL）が発動する条件、対象になるトレーダーの順位の決まり方、保険基金との関係と回避のポイントを解説します。","related":[["insurance-fund","保険基金（インシュアランスファンド）","保険基金とは、先物取引所が強制ロスカットで証拠金を超える損失が出たときの穴埋めに使うために積み立てている資金で、自動デレバレッジの発動を防ぐ役割を持ちます。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["unrealized-pnl","含み損益（未実現損益）","含み損益（未実現損益）とは、まだ決済していないポジションについて、現在の価格で決済したと仮定した場合の利益または損失のことです。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"強制決済（清算）：強制終了のボタンを押したのは誰か"},"coin":null,"tool":"/liquidations","cta":false},"crypto-wallet":{"slug":"crypto-wallet","cat":"wallets-security","en":"Crypto wallet","contentLocale":"ja","term":"暗号資産ウォレット（仮想通貨ウォレット）","aka":["ウォレット","仮想通貨ウォレット","クリプトウォレット","crypto wallet"],"short":"暗号資産ウォレットとは、暗号資産を送受信するための秘密鍵とアドレスを管理するアプリや機器のことで、コインそのものではなく、それを動かす鍵を保管しています。","body":[[["暗号資産","cryptocurrency"],"は",["ブロックチェーン","blockchain"],"上に記録されていて、ウォレットの中に入っているわけではありません。ウォレットが持っているのは、その資産を動かすための",["秘密鍵","private-key"],"です。秘密鍵から受け取り用の",["アドレス","wallet-address"],"が作られ、送金するときは秘密鍵で取引に署名します。秘密鍵を失えば資産を動かせなくなり、他人に知られれば資産を盗まれます。"],["ウォレットは大きく2種類に分かれます。取引所などのサービスが鍵を管理する",["カストディアル","custodial-wallet"],"型と、自分で鍵を管理するノンカストディアル型（",["セルフカストディ","non-custodial-wallet"],"）です。また、インターネットにつながったホットウォレットと、オフラインで鍵を保管するコールドウォレット（ハードウェアウォレットなど）という分け方もあります。"],"自分で管理するウォレットを作ると、12語や24語のシードフレーズ（リカバリーフレーズ）が表示されます。これは秘密鍵の元になる情報で、これさえあれば別の端末でウォレットを復元できます。紙に書いてオフラインで保管し、写真やクラウドに保存しないこと、誰にも教えないことが基本です。"],"example":"ノンカストディアルのウォレットアプリを作ると、12語のシードフレーズとETHの受け取りアドレスが作られたとします。取引所から0.2 ETHをこのアドレスへ出金し、そこからさらに友人へ0.05 ETHを送る場合、送金にはETHのガス代がかかります。ガス代が0.0005 ETHなら、手元には0.2−0.05−0.0005＝0.1495 ETHが残ります。スマートフォンをなくしても、シードフレーズで新しい端末に復元すれば同じ残高が見られます。","mistakes":["シードフレーズをスクリーンショットやクラウドのメモに保存する。","サポートを名乗る人物に、確認のためと言われてシードフレーズを教えてしまう。","送金先のネットワーク（チェーン）を確認せず、対応していないネットワークで送金する。"],"faq":[{"q":"暗号資産はウォレットの中に入っているのですか？","a":"いいえ、資産はブロックチェーン上に記録されています。ウォレットはその資産を動かすための秘密鍵を管理しています。"},{"q":"取引所の口座もウォレットですか？","a":"取引所の口座は、取引所が鍵を管理するカストディアルウォレットの一種と考えられます。自分で鍵を持つウォレットとは管理責任が異なります。"}],"title":"暗号資産ウォレットとは？仕組みと種類","description":"暗号資産ウォレットの仕組み、秘密鍵とアドレスの関係、カストディアルとノンカストディアル、シードフレーズの安全な保管方法を解説します。","related":[["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。"],["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。"],["seed-phrase","シードフレーズ（リカバリーフレーズ）","シードフレーズとは、ウォレットの秘密鍵をすべて復元できる12語または24語の英単語の並びで、ウォレットのマスターキーにあたるものです。"],["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["hardware-wallet","ハードウェアウォレット","ハードウェアウォレットとは、秘密鍵を専用の小型デバイス内に保管し、送金の署名を端末の中だけで行う物理的な暗号資産ウォレットです。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":null,"cta":false},"memo-tag":{"slug":"memo-tag","cat":"wallets-security","en":"Memo / destination tag","contentLocale":"ja","term":"メモ／宛先タグ（Memo・Destination Tag）","aka":["メモ","宛先タグ","デスティネーションタグ","Memo","Tag"],"short":"メモ（宛先タグ）とは、XRPやXLMなど一部の暗号資産で、同じ入金アドレスを共有する利用者の中から受取人を特定するための追加の番号や文字列です。","body":[["取引所は、XRP、XLM、EOS、ATOM、TONなど一部の銘柄で、多くの利用者に共通の",["入金アドレス","wallet-address"],"を使っています。そこで誰の入金かを区別するために、利用者ごとのメモやタグを発行します。"],["送金時にメモを入れ忘れたり間違えたりすると、資金は取引所のアドレスには届いても、あなたの口座には反映されません。多くの場合は",["サポート","support-and-resistance"],"への申請で復旧できますが、時間がかかったり手数料がかかったりすることがあります。"],"取引所によって「メモ」「タグ」「Destination Tag」「コメント」など呼び名が違います。入金画面にメモ欄が表示されたら、アドレスと同じくらい重要な情報だと考えてください。"],"example":"取引所Bの入金画面で、XRPの入金アドレスとともに宛先タグ「104857」が表示されたとします。取引所Aの出金画面では、アドレス欄にアドレスを、タグ欄に104857を入力して300 XRPを送ります。タグが空欄のまま送ると、300 XRPは取引所Bの共通アドレスに届くものの、誰の分か判別できず口座残高は0のままになります。","mistakes":["メモ欄を任意入力だと思い込み、空欄のまま送金すること。","別の銘柄や以前の入金時のメモを使い回すこと。","個人ウォレットへの送金で、不要なメモを求められたと勘違いして別の値を入れること。"],"faq":[{"q":"メモを入れ忘れた場合、資産は戻りますか？","a":"受取側が取引所なら、取引ハッシュ（TxID）などを添えてサポートに申請すると復旧できる場合が多いです。ただし対応や手数料は取引所ごとに異なります。"},{"q":"自分のウォレットに送るときもメモは必要ですか？","a":"個人ウォレットのアドレスは自分専用なので、通常メモは不要です。ただし受取側の案内に必要と書かれていれば、それに従ってください。"}],"title":"メモ・宛先タグとは？入れ忘れたときの対処","description":"XRPなどの送金で必要なメモ（宛先タグ）の意味、入れ忘れたときに起こること、取引所での正しい入力方法を解説します。","related":[["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["blockchain-network","送金ネットワーク（チェーン選択）","送金ネットワークとは、暗号資産を入出金するときにどのブロックチェーン上で送るかを指定する項目で、送金側と受取側で一致させる必要があります。"],["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"two-factor-authentication":{"slug":"two-factor-authentication","cat":"wallets-security","en":"Two-factor authentication (2FA)","contentLocale":"ja","term":"二段階認証（2FA）","aka":["2FA","二要素認証","2段階認証","two-factor authentication"],"short":"二段階認証（2FA）とは、パスワードに加えて認証アプリのコードやセキュリティキーなど別の要素を求めることで、不正ログインを防ぐ仕組みです。","body":["取引所では、ログイン、出金、APIキーの作成、セキュリティ設定の変更などで2FAが求められます。パスワードが漏れても、2つ目の要素がなければ攻撃者は操作を完了できません。","方式によって強さが異なります。一般に、SMS認証はSIMスワップ（電話番号の乗っ取り）の被害例があるため、Google Authenticatorなどの認証アプリや、物理的なセキュリティキー（パスキーを含む）の方が強いとされています。",["認証アプリを設定するときに表示されるバックアップキーは、スマホを機種変更・紛失したときの復旧に必要です。",["シードフレーズ","seed-phrase"],"と同じく、オフラインで保管しておきましょう。"]],"example":"認証アプリのコードは6桁の数字で、通常30秒ごとに新しくなります。6桁なら100万通りの組み合わせがあり、しかも30秒で無効になるため、パスワードだけを盗んだ攻撃者が当てずっぽうで突破するのは困難です。ただし、偽サイトにパスワードと6桁のコードをその場で入力してしまうと、攻撃者はそのコードが有効な30秒以内に本物のサイトへログインできます。","mistakes":["セキュリティが弱いSMS認証だけに頼り、認証アプリやセキュリティキーを設定しないこと。","バックアップキーを保存せずに機種変更し、自分の口座にログインできなくなること。","電話やチャットで「確認のため」と言われて6桁のコードを読み上げてしまうこと。"],"faq":[{"q":"SMS認証と認証アプリはどちらが安全ですか？","a":"一般的には認証アプリの方が安全とされています。SMSは電話番号の乗っ取りで受信される可能性があるためです。さらに強い対策として物理セキュリティキーがあります。"},{"q":"スマホをなくして2FAが使えなくなったらどうしますか？","a":"保管しておいたバックアップキーで認証アプリを復元します。バックアップがない場合は、取引所の本人確認を伴うリセット手続きが必要で、時間がかかることがあります。"}],"title":"二段階認証（2FA）とは？取引所での設定と注意点","description":"暗号資産取引所の二段階認証（2FA）の意味、SMSと認証アプリの違い、機種変更時のバックアップなど安全に使うポイントを解説します。","related":[["anti-phishing-code","フィッシング対策コード","フィッシング対策コードとは、取引所から届く正規のメールに利用者が設定した合言葉を表示させ、偽メールと見分けやすくする機能です。"],["withdrawal-whitelist","出金ホワイトリスト","出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。"],["phishing","フィッシング詐欺","フィッシング詐欺とは、取引所やウォレットを装った偽のサイト、メール、メッセージで、ログイン情報やシードフレーズを入力させたり、悪意ある取引に署名させたりする詐欺です。"],["sub-account","サブアカウント","サブアカウントとは、1つのメインアカウントの下に作成できる独立した口座で、資金や取引、APIキーを用途ごとに分けて管理するための取引所の機能です。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"本物の扉を見極める：やみくもに口座開設しないこと"},"coin":null,"tool":null,"cta":false},"withdrawal-whitelist":{"slug":"withdrawal-whitelist","cat":"wallets-security","en":"Withdrawal whitelist","contentLocale":"ja","term":"出金ホワイトリスト","aka":["出金アドレスホワイトリスト","アドレス帳ロック","withdrawal whitelist"],"short":"出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。","body":[["ホワイトリストを有効にすると、登録済みの",["アドレス","wallet-address"],"以外への出金はできなくなります。万一アカウントに不正ログインされても、攻撃者が自分のアドレスへ資産を送ることを難しくする仕組みです。"],"多くの取引所では、新しいアドレスを追加する際に2FAやメール認証を求め、さらに追加後の一定時間は出金できないよう待機期間を設けています。この待機期間の長さや設定方法は取引所ごとに異なります。","アドレスを登録するときは、登録作業そのものが最大の注意点になります。偽アドレスや間違ったネットワークのアドレスを登録すると、その後は毎回同じ間違った先へ送ってしまいます。"],"example":["あなたが自分の",["ハードウェアウォレット","hardware-wallet"],"と、よく使う別の取引所の2つのアドレスだけをホワイトリストに登録しているとします。ある日パスワードが漏れて不正ログインされ、攻撃者が3 ETHを外部へ出金しようとしても、未登録アドレスへの出金はブロックされます。攻撃者が新しいアドレスを追加しようとすれば2FAが必要で、さらに待機期間がある取引所なら、その間に通知に気付いて口座を凍結できます。"],"mistakes":["取引履歴からアドレスをコピーして登録し、似せた偽アドレスを紛れ込ませること。","ホワイトリストに登録するアドレスのネットワークを確認しないこと。","便利さのためにホワイトリストを無効にしたまま、戻し忘れること。"],"faq":[{"q":"ホワイトリストを有効にすると不便になりませんか？","a":"新しい送金先のたびに登録作業が必要になりますが、頻繁に使う送金先は数か所に限られることが多いです。安全性とのバランスを考えると、多くの人にとって有効にする価値があります。"},{"q":"ホワイトリストがあれば不正出金は完全に防げますか？","a":"大きく難しくはなりますが、メールや2FAまで乗っ取られれば突破される可能性があります。2FAやフィッシング対策コードと組み合わせて使いましょう。"}],"title":"出金ホワイトリストとは？仕組みと設定のポイント","description":"取引所の出金ホワイトリストの意味、不正出金を防ぐ仕組み、アドレス登録時に気を付けるべきポイントをわかりやすく解説します。","related":[["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["two-factor-authentication","二段階認証（2FA）","二段階認証（2FA）とは、パスワードに加えて認証アプリのコードやセキュリティキーなど別の要素を求めることで、不正ログインを防ぐ仕組みです。"],["address-poisoning","アドレスポイズニング","アドレスポイズニングとは、本物の送金先とよく似たアドレスから少額や0円の取引を送りつけ、取引履歴から偽アドレスをコピーさせて誤送金を誘う詐欺です。"],["anti-phishing-code","フィッシング対策コード","フィッシング対策コードとは、取引所から届く正規のメールに利用者が設定した合言葉を表示させ、偽メールと見分けやすくする機能です。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"crypto-backed-stablecoin":{"slug":"crypto-backed-stablecoin","cat":"stablecoins","en":"Crypto-backed stablecoin","contentLocale":"ja","term":"暗号資産担保型ステーブルコイン","aka":["暗号資産担保型","クリプト担保型ステーブルコイン"],"short":"暗号資産担保型ステーブルコインとは、ETHなどの暗号資産をスマートコントラクトに預け入れ、その担保価値を上回らない範囲で発行されるステーブルコインのことです。","body":[["法定通貨担保型のUSDTやUSDCが銀行預金や短期国債を裏付けにするのに対し、暗号資産担保型は",["ブロックチェーン","blockchain"],"上の",["暗号資産","cryptocurrency"],"を担保にします。代表例はDAI（現在はSky関連のUSDSも）で、ユーザーがETHなどを預けて",["ステーブルコイン","stablecoin"],"を借りる形で発行されます。"],["担保の暗号資産は値動きが大きいため、多くの場合「過剰担保」が採用されています。たとえば150ドル分の担保で100ドル分しか発行できない、という仕組みです。担保価値が一定の比率を下回ると、担保が自動的に売却される清算（",["ロスカット","liquidation"],"）が実行されます。"],["利点は、担保の状況をブロックチェーン上で誰でも確認できる透明性です。一方で、相場の急落時に清算が連鎖したり、",["スマートコントラクト","smart-contract"],"の不具合が起きたりするリスクがあります。担保比率や清算ラインはプロトコルごとに異なります。"]],"example":"ETHが3,000ドルのときに、あなたが1 ETHを預けて1,500 DAIを発行したとします。担保比率は3,000÷1,500で200%です。このプロトコルの清算ラインが150%だとすると、担保価値が2,250ドルを下回ると清算対象になります。つまりETHが2,250ドルまで下がると担保が売却され、ペナルティも差し引かれます。ETHが2,500ドルに下がった時点で500 DAIを返済しておけば、残りの1,000 DAIに対して担保比率は250%となり、清算までの余裕が広がります。","mistakes":["発行できる上限いっぱいまでステーブルコインを借りてしまい、少しの下落で清算される。","担保比率を定期的に確認せず、急落した夜間に清算されてから気づく。","清算ラインと清算ペナルティがプロトコルごとに違うことを知らずに、別のサービスでも同じ感覚で借りてしまう。"],"faq":[{"q":"DAIは何を担保にしていますか？","a":"当初はETHなどの暗号資産が中心でしたが、現在はUSDCなどのステーブルコインや現実資産も担保に組み込まれています。構成は変わるため、公式の担保状況ページで確認するのが確実です。"},{"q":"なぜ過剰担保が必要なのですか？","a":"担保となる暗号資産の価格が大きく動くためです。担保に余裕を持たせることで、価格が下がってもステーブルコインの価値を保てるようにしています。"}],"title":"暗号資産担保型ステーブルコインとは？仕組みと清算","description":"暗号資産担保型ステーブルコインの仕組み、過剰担保と清算ラインの考え方、DAIを例にした計算とよくある失敗を解説します。","related":[["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["defi-lending","DeFiレンディング","DeFiレンディングとは、スマートコントラクト上で暗号資産を貸し出して利息を得たり、担保を預けて別の暗号資産を借りたりできる仕組みです。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["algorithmic-stablecoin","アルゴリズム型ステーブルコイン","アルゴリズム型ステーブルコインとは、十分な担保ではなく、供給量を自動調整するプログラムや別トークンとの交換の仕組みによって価格を1ドルに保とうとするステーブルコインです。"]],"lesson":null,"coin":{"slug":"dai","name":"Dai","symbol":"DAI"},"tool":null,"cta":false},"block-explorer":{"slug":"block-explorer","cat":"onchain","en":"Block explorer","contentLocale":"ja","term":"ブロックエクスプローラー","aka":["エクスプローラー","block explorer"],"short":"ブロックエクスプローラーとは、ブロックチェーン上の取引、アドレスの残高、ブロックの情報を検索して閲覧できるウェブサービスのことです。","body":[["送金後に発行される",["トランザクションハッシュ（TxID）","transaction-hash"],"や",["ウォレットアドレス","wallet-address"],"を入力すると、その取引が成功したか、何回の承認（",["コンファメーション","block-confirmations"],"）を得たか、手数料はいくらだったかを確認できます。",["ビットコイン","bitcoin"],"にはmempool.space、",["イーサリアム","ethereum"],"にはEtherscan、トロンにはTronscanなど、チェーンごとに代表的なエクスプローラーがあります。"],"取引所への入金が反映されないときに最初に確認するのがエクスプローラーです。「成功」と表示されていれば送金自体は完了しており、取引所側の必要承認数を待っているか、入金処理の問題を問い合わせる段階だとわかります。","注意したいのは、送金したネットワークに対応したエクスプローラーを使うことです。USDTのように複数のチェーンで発行されているトークンは、イーサリアム上の送金はEtherscan、トロン上の送金はTronscanで検索しないと見つかりません。"],"example":["あなたが取引所から",["ウォレット","crypto-wallet"],"へ500 USDTをトロン（TRC20）で出金し、30分経っても届かないとします。取引所の出金履歴からTxIDをコピーしてTronscanで検索すると、状態が「成功」、受取アドレスがあなたのアドレスと一致し、数量も500と表示されました。この場合、資金はすでにブロックチェーン上で届いています。ウォレットアプリでトロンのネットワークが表示されていない、またはUSDTトークンが追加されていないだけの可能性が高く、送金のやり直しは不要です。"],"mistakes":["送金したチェーンとは別のエクスプローラーで検索し、「取引が存在しない」と慌てる。","エクスプローラーを装った偽サイトにウォレットを接続したり、シードフレーズを入力したりしてしまう。","承認数が足りずに取引所へ未反映なだけなのに、同じ送金をもう一度してしまう。"],"faq":[{"q":"ブロックエクスプローラーで他人の残高も見られますか？","a":"はい、アドレスさえわかれば誰でも残高と取引履歴を見られます。そのため、アドレスと本人が結びつくと資産状況が知られる点に注意が必要です。"},{"q":"エクスプローラーを使うのにウォレット接続は必要ですか？","a":"閲覧だけなら接続は不要です。閲覧目的で接続や署名を求められた場合は、偽サイトを疑ってください。"}],"title":"ブロックエクスプローラーとは？使い方と送金確認","description":"ブロックエクスプローラーの意味と使い方、TxIDで送金状況を確認する手順、チェーンを間違えないための注意点を解説します。","related":[["transaction-hash","トランザクションハッシュ（TxID）","トランザクションハッシュ（TxID）とは、ブロックチェーン上の個々の取引に付けられる固有の識別子で、送金の状況を誰でも確認できる「追跡番号」の役割を果たします。"],["block-confirmations","ブロック承認数（コンファメーション）","ブロック承認数とは、取引が含まれたブロックの後にいくつのブロックが積み重なったかを示す数で、多いほど取引が覆される可能性が低くなります。"],["wallet-address","ウォレットアドレス","ウォレットアドレスとは、暗号資産を受け取るための英数字の文字列で、銀行の口座番号のようにブロックチェーン上の送金先を表すものです。"],["on-chain-analysis","オンチェーン分析","オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"「送金完了」と出ているのに届かない。どこを調べるべき？"},"coin":null,"tool":null,"cta":false},"travel-rule":{"slug":"travel-rule","cat":"regulation","en":"Travel rule","contentLocale":"ja","term":"トラベルルール","aka":["Travel Rule","FATFトラベルルール"],"short":"トラベルルールとは、暗号資産を取引所間などで送るときに、送金人と受取人の氏名などの情報を事業者同士で共有することを求める国際的なルールです。","body":[["トラベルルールは、FATF（金融活動作業部会）の勧告16にもとづくもので、もともと銀行送金に適用されていた考え方を",["暗号資産","cryptocurrency"],"にも広げたものです。FATFのガイダンスでは1,000ドルまたは1,000ユーロ相当がひとつの目安とされていますが、EUでは2024年12月30日から金額にかかわらず適用されるなど、国によって基準が異なります。日本でも2023年から導入されています。"],"実際の手続きとしては、取引所から出金するときに「送金先の取引所名」「受取人の氏名」「自分の口座への送金かどうか」などを入力するよう求められます。入金側でも、どこから送られてきたかの確認を求められることがあります。",["やっかいなのは、取引所ごとに使っている情報共有の仕組みが違い、相手先に対応していないと送金できない場合があることです。送金前に、送り先の取引所が対応しているか、個人の",["ウォレット","crypto-wallet"],"宛てならどんな申告が必要かを確認しておきましょう。"]],"example":"あなたが国内の取引所Aから海外の取引所Bへ、1,500 USDTを送りたいとします。取引所Aの出金画面で、送金先として取引所Bを選び、受取人の氏名と居住国を入力する必要があります。もし取引所Aと取引所Bが同じ情報共有の仕組みに対応していなければ、出金そのものが受け付けられないことがあります。その場合は、いったん自分の個人ウォレットに出金し、本人のウォレットであることを申告してから取引所Bへ送る、という手順になることがあります。","mistakes":["受取人の氏名を取引所に登録されている表記と違う形で入力し、送金が差し戻される。","送金先の取引所が対応しているか確認せずに出金しようとし、手続きの途中で止まる。","自分の別口座への送金でも申告が必要なことを知らず、入金が保留される。"],"faq":[{"q":"トラベルルールは個人ウォレットへの送金にも適用されますか？","a":"国や取引所によって扱いが異なりますが、送金先が本人のウォレットかどうか、相手の名前などの申告を求められることが多いです。"},{"q":"トラベルルールで送金できない場合はどうすればよいですか？","a":"送金元と送金先の取引所が対応している情報共有の仕組みを確認し、対応していなければ個人ウォレットを経由する方法などを各取引所の案内に沿って検討します。"}],"title":"トラベルルールとは？暗号資産送金で必要な情報","description":"暗号資産のトラベルルールの意味、FATF勧告16との関係、取引所間の送金で求められる情報と送金できない場合の対処法を解説します。","related":[["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["aml","AML（マネーロンダリング対策）","AMLとは、犯罪で得た資金の出どころを隠す行為（マネーロンダリング）を防ぐために、金融機関や暗号資産取引所が行う監視・確認・報告の仕組み全体のことです。"],["vasp","VASP（暗号資産サービス提供者）","VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。"],["withdrawal-whitelist","出金ホワイトリスト","出金ホワイトリストとは、あらかじめ登録した送金先アドレスにだけ出金できるよう制限する取引所のセキュリティ機能です。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"送金する前に：推測で済ませてはいけない必須項目"},"coin":null,"tool":null,"cta":false},"spot-bitcoin-etf":{"slug":"spot-bitcoin-etf","cat":"regulation","en":"Spot bitcoin ETF","contentLocale":"ja","term":"ビットコイン現物ETF","aka":["ビットコインETF","現物ETF","spot bitcoin ETF"],"short":"ビットコイン現物ETFとは、運用会社が実際のビットコインを保有し、その価格に連動するよう設計された、証券取引所に上場している投資信託のことです。","body":[["米国では2024年1月にビットコイン現物ETFの取引が始まりました。投資家は",["暗号資産","cryptocurrency"],"取引所の口座や",["ウォレット","crypto-wallet"],"を使わずに、証券会社の口座から株式と同じようにETFを売買できます。",["ビットコイン","bitcoin"],"の保管はカストディ業者が担当します。"],["先物ETFは",["先物契約","futures-contract"],"を保有するため、限月の乗り換えコストなどで現物価格とずれが出やすいのに対し、現物ETFは実際のビットコインを保有するので価格の連動性が高いのが特徴です。ただし、信託報酬（経費率）が毎年差し引かれ、ETFの売買は証券取引所の取引時間中に限られます。"],["ETFを買っても、あなた自身がビットコインを受け取ったり、",["ブロックチェーン","blockchain"],"上で送金したりすることはできません。どの国のETFを、どの証券会社で買えるかは、各国の制度によって異なります。"]],"example":["あなたが現物ETFに100万円分投資し、その年の経費率が0.25%だったとします。ビットコインの価格がまったく変わらなかった場合、1年後の評価額は経費の分だけ減り、約997,500円になります。一方、取引所で100万円分のビットコインを直接買う場合は、売買手数料や",["スプレッド","bid-ask-spread"],"を払う代わりに、毎年の経費はかかりません。また、ETFは週末に取引できないので、土曜日にビットコインが10%動いても、ETFの価格に反映されるのは月曜日の取引開始後です。"],"mistakes":["ETFを買えば自分のウォレットにビットコインを送れると考えてしまう。","経費率を確認せず、長期保有での差を見落とす。","ETFの取引時間外にも、ビットコインと同じように24時間売買できると思い込む。"],"faq":[{"q":"ビットコイン現物ETFと先物ETFの違いは何ですか？","a":"現物ETFは実際のビットコインを保有し、先物ETFはビットコイン先物の契約を保有します。先物ETFは限月の乗り換えにかかるコストなどで、現物価格とのずれが出やすくなります。"},{"q":"日本でビットコイン現物ETFを買えますか？","a":"購入できるかどうかは日本の制度と各証券会社の取り扱いによって異なり、制度の見直しによって変わる可能性があります。利用する証券会社の最新の案内を確認してください。"}],"title":"ビットコイン現物ETFとは？意味と直接購入との違い","description":"ビットコイン現物ETFの意味と仕組み、先物ETFや取引所での直接購入との違い、経費率や取引時間など注意すべき点を解説します。","related":[["bitcoin","ビットコイン（BTC）","ビットコイン（BTC）とは、2009年に運用が始まった最初の暗号資産で、発行上限2100万枚、管理者のいないネットワークでプルーフ・オブ・ワークにより運営されています。"],["tokenized-stocks","トークン化株式","トークン化株式とは、実際の株式や株式に連動する権利をブロックチェーン上のトークンとして発行し、暗号資産と同じように保有や送金ができるようにしたものです。"],["custodial-wallet","カストディアルウォレット（管理型ウォレット）","カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。"],["market-capitalization","時価総額（マーケットキャップ）","時価総額（マーケットキャップ）とは、暗号資産の現在価格に流通供給量を掛けた値で、その銘柄の市場規模を比べるための基本的な指標です。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"geo-restrictions":{"slug":"geo-restrictions","cat":"regulation","en":"Geo-restrictions (restricted regions)","contentLocale":"ja","term":"地域制限（利用制限国）","aka":["ジオブロック","利用制限地域","geo-restrictions"],"short":"地域制限とは、暗号資産取引所などが法律や規制上の理由から、特定の国や地域に住む人に対してサービスの全部または一部を提供しないことです。","body":[["取引所は、各国の規制やライセンスの状況に応じて、サービスを提供できる地域を決めています。規約には「利用制限国（Restricted Jurisdictions）」の一覧があり、その国の居住者は口座開設できないか、先物や",["ステーキング","staking"],"など一部の商品だけ使えないことがあります。"],["制限は、アクセス元のIP",["アドレス","wallet-address"],"、登録した居住国、KYCで提出した身分証や住所によって判断されます。登録はできても、KYCの段階で居住国が対象外と判明して利用が止まるケースも少なくありません。"],"日本の居住者について言えば、国内で登録されていない一部の海外取引所は、日本居住者の新規登録を受け付けていなかったり、サービスを段階的に終了したりしています。規約は変わることがあるため、使い始める前と、大きな金額を預ける前に確認するのが安全です。"],"example":["あなたが海外の取引所で口座を作り、2,000 USDTを入金して",["先物取引","futures-contract"],"を始めようとしたとします。ところが、KYCで日本の住所を登録したところ、その取引所では日本居住者は先物取引の対象外で、",["現物取引","spot-trading"],"だけが使えると表示されました。この場合、2,000 USDTは現物取引か出金にしか使えません。もしVPNで別の国からアクセスしていたことが後で判明すると、規約違反として口座が凍結され、出金に追加の審査が必要になることもあります。"],"mistakes":["VPNを使えば地域制限を回避できると考え、規約違反で口座を凍結される。","登録できたので問題なく使えると考え、KYCの段階での制限を確認しない。","現物は使えても先物やステーキングは対象外、といった商品ごとの制限を見落とす。"],"faq":[{"q":"VPNで地域制限を回避してもよいですか？","a":"多くの取引所の規約では禁止されており、発覚すると口座の凍結や出金の制限につながります。規約上利用できる取引所を選ぶのが確実です。"},{"q":"利用制限国の一覧はどこで確認できますか？","a":"各取引所の利用規約やヘルプセンターに掲載されています。商品ごとに対象国が違う場合もあるので、使いたい商品の案内まで確認してください。"}],"title":"地域制限とは？取引所の利用制限国の意味","description":"暗号資産取引所の地域制限（利用制限国）の意味、制限が判断される仕組み、VPN利用のリスクと口座開設前の確認ポイントを解説します。","related":[["kyc","KYC（本人確認）","KYCとは、暗号資産取引所や金融機関が口座開設時などに、身分証明書や顔写真によって利用者の本人確認を行う手続きのことです。"],["vasp","VASP（暗号資産サービス提供者）","VASPとは、暗号資産の交換、送金、保管などのサービスを業として提供する事業者を指すFATFの用語で、取引所やカストディ業者などが該当します。"],["no-kyc-exchange","KYC不要の取引所（ノーKYC取引所）","KYC不要の取引所とは、身分証明書による本人確認なしで登録や取引、一定額までの出金ができる暗号資産取引所や交換サービスのことです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC（本人確認）の仕組みと、身分証は誰に提出すべきか？"},"coin":null,"tool":"/exchanges","cta":false},"delisting":{"slug":"delisting","cat":"exchange-features","en":"Delisting","contentLocale":"ja","term":"上場廃止（デリスティング）","aka":["取扱廃止","デリスト","delisting"],"short":"上場廃止とは、取引所がある暗号資産の取扱いを終了し、その取引所での売買、さらに一定期間後には入金や出金もできなくなることです。","body":[["取引所が上場廃止を決める理由には、",["取引量","trading-volume"],"や",["流動性","liquidity"],"の低下、プロジェクトの開発停止、セキュリティ上の問題、規制への対応などがあります。上場廃止の発表では、取引の終了日時、入金の停止日、出金の期限が案内されるのが一般的です。"],"上場廃止が発表されると、その取引所での売りが集中し、価格が大きく下がることがあります。先物の取扱いが先に終わり、保有中のポジションが決められた価格で強制的に決済される場合もあります。",["出金の期限を過ぎると、取引所が残高を別の通貨に交換したり、手続きが煩雑になったりすることがあります。他の取引所で取り扱いが続いているか、自分の",["ウォレット","crypto-wallet"],"に出金できるネットワークがあるかを早めに確認しましょう。"]],"example":["あなたがある取引所で、トークンXを20,000枚、1枚0.05 USDTで保有していたとします。評価額は1,000 USDTです。取引所が2週間後に取引を終了し、出金は3か月後まで可能だと発表しました。発表直後に価格が0.035 USDTまで下がると、評価額は700 USDTになります。この時点で売るか、トークンXを扱う別の取引所や自分のウォレットに出金するかを選べます。",["出金手数料","withdrawal-fee"],"が1回200枚分なら、出金後に手元に残るのは19,800枚です。期限を過ぎてから慌てないよう、発表後すぐに対応を決めておくことが大切です。"],"mistakes":["上場廃止の告知を見落とし、出金期限を過ぎてから資産に気づく。","発表直後のパニック売りに巻き込まれ、他の取引所の価格を確認せずに安値で売る。","先物ポジションが取扱い終了時に強制決済されることを知らず、そのまま放置する。"],"faq":[{"q":"上場廃止になったトークンはどうなりますか？","a":"その取引所では売買できなくなりますが、トークン自体が消えるわけではありません。他の取引所やDEXで取引が続いている場合もあります。"},{"q":"上場廃止の前に何をすべきですか？","a":"売却するか、他の取引所や自分のウォレットへ出金するかを、出金期限の前に決めておきます。送金先が対応しているネットワークの確認も忘れないでください。"}],"title":"上場廃止とは？暗号資産のデリスティングと対処法","description":"暗号資産の上場廃止（デリスティング）の意味と理由、発表後の価格変動、取引終了日と出金期限までにやるべきことを解説します。","related":[["token-listing","上場（トークン上場）","トークン上場とは、取引所が新しい暗号資産の取扱いを開始し、利用者がその取引所で入金・売買・出金できるようにすることです。"],["liquidity","流動性（リクイディティ）","流動性とは、ある暗号資産を価格を大きく動かさずに、すぐ売買できる度合いのことで、板の厚みやスプレッドの狭さで判断します。"],["withdrawal-fee","出金手数料","出金手数料とは、取引所から外部のウォレットや他の取引所へ暗号資産を送るときに差し引かれる手数料で、主にブロックチェーンのネットワーク手数料をまかなうためのものです。"],["rug-pull","ラグプル","ラグプルとは、暗号資産プロジェクトの開発者が流動性や集めた資金を突然引き揚げ、トークンの価格をほぼゼロにして投資家に損失を負わせる詐欺的な行為です。"]],"lesson":null,"coin":null,"tool":"/activities","cta":false}});
